    boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
    if (unique) {
        level++;
    }
    level = Math.min(level, 3);
    boolean tenured = this.registrationDate != null
        && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
    if (tenured) {
