560	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
561	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
562	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
563	     * {@code <REGION>} segment baked into the {@code customerCode}.
564	     *
565	     * @param postcode the owner's postcode, or {@code null}
566	     * @return the region code, or {@code 'UNKNOWN'}
567	     */
568	    private String regionForPostcode(String postcode) {
569	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
570	            return "UNKNOWN";
571	        }
572	        int value = Integer.parseInt(postcode);
573	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
574	            int[] range = entry.getValue();
575	            if (value >= range[0] && value <= range[1]) {
576	                return entry.getKey();
577	            }
578	        }
579	        return "UNKNOWN";
580	    }
581	
582	    /**
583	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
584	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
585	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
586	     * region.
587	     *
588	     * @param city the owner's city
589	     * @return the region code, or {@code 'UNKNOWN'}
590	     */
591	    private String regionForCity(String city) {
592	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
593	    }
594	
595	    /**
596	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
597	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
598	     * deterministic {@code householdId} (length 12).
599	     *
600	     * @param input  the value to hash
601	     * @param length the number of leading hex characters to return
602	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
603	     */
604	    private String hashHex(String input, int length) {
605	        try {
606	            byte[] digest = MessageDigest.getInstance("SHA-256")
607	                .digest(input.getBytes(StandardCharsets.UTF_8));
608	            StringBuilder hex = new StringBuilder(digest.length * 2);
609	            for (byte b : digest) {
610	                hex.append(String.format("%02x", b));
611	            }
612	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
613	        } catch (NoSuchAlgorithmException e) {
614	            throw new IllegalStateException("SHA-256 algorithm not available", e);
615	        }
616	    }
